'use strict';
const app=document.querySelector('#app'),notice=document.querySelector('#notice'),path=location.pathname;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format(Number(v)/100);
const date=v=>v?new Date(v).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}):'';
const day=v=>v?new Date(v).toLocaleDateString('en-IN',{timeZone:'Asia/Kolkata',dateStyle:'long'}):'';
const csrf=()=>decodeURIComponent(document.cookie.split('; ').find(v=>v.startsWith('bc_csrf='))?.split('=')[1]||'');
const uuid=()=>crypto.randomUUID();
function message(text,error=false){notice.textContent=text;notice.className=error?'error':'';if(text)notice.focus();}
// Every request counts toward the bar across the top of the page, shown only
// once one has taken long enough to notice, so fast screens do not flicker.
let pending=0,progressTimer;
let sessionEnding=false;
function endStaffSession(){if(sessionEnding)return;sessionEnding=true;sessionStorage.setItem('bc_staff_session_ended','1');location.reload();}
async function checkStaffResponse(res,url){if(res.status!==401||!url.startsWith('/admin/')||(url==='/admin/me'&&!me))return;endStaffSession();
// Navigation discards this page. Keep old handlers from rendering errors or
// saved data over sign-in while concurrent requests finish.
await new Promise(()=>{});}
function progress(step){pending+=step;const bar=document.getElementById('progress');if(!bar)return;clearTimeout(progressTimer);if(pending<1)bar.hidden=true;else if(bar.hidden)progressTimer=setTimeout(()=>{bar.hidden=false;},150);}
async function api(url,opts={}){const headers={'Content-Type':'application/json',...opts.headers};if(opts.method)headers['X-CSRF-Token']=csrf();progress(1);try{let res;try{res=await fetch('/api/v1'+url,{...opts,headers});}catch(e){if(e.name==='AbortError')throw e;throw Error('Network error. Check your connection and retry.');}await checkStaffResponse(res,url);const out=await res.json().catch(()=>null);if(!res.ok)throw Error(out?.error||`Request failed (${res.status}). Please retry.`);if(out===null)throw Error('Unexpected response. Please retry.');return out;}finally{progress(-1);}}
const post=(url,body,headers={})=>api(url,{method:'POST',body:JSON.stringify(body),headers});
// #notice lives outside #app, so replacing the screen never cleared it: a failed
// sign-in outlived the successful one that followed, and every screen after it.
// Clearing at the start of an action rather than on render is deliberate -
// handlers that report progress ("Saving registration…") set their message after
// this point, so it survives the re-render they trigger.
function bind(id,event,fn){document.getElementById(id)?.addEventListener(event,async e=>{message('');try{await fn(e);}catch(err){message(err.message,true);}});}
async function busy(button,fn,busyText='Saving…'){const text=button.textContent;button.disabled=true;button.textContent=busyText;button.classList.add('is-busy');button.setAttribute('aria-busy','true');try{return await fn();}finally{if(button.isConnected){button.disabled=false;button.textContent=text;button.classList.remove('is-busy');button.removeAttribute('aria-busy');}}}
function field(label,name,value='',type='text',extra=''){return `<label>${esc(label)}<input name="${esc(name)}" value="${esc(value)}" type="${type}" ${extra} required></label>`;}
function pairs(items){return `<dl class="review-list">${items.map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl>`;}
function table(items,columns){if(!items.length)return '<p class="muted">No records yet.</p>';return `<div class="table-scroll"><table><thead><tr>${columns.map(([k,l])=>`<th scope="col">${esc(l)}</th>`).join('')}</tr></thead><tbody>${items.map(item=>`<tr>${columns.map(([k])=>`<td>${esc(item[k]??'')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function paise(v){if(!/^\d+(\.\d{1,2})?$/.test(String(v)))throw Error('Use a positive amount with at most two decimal places.');const [n,d='']=String(v).split('.'),p=Number(n)*100+Number(d.padEnd(2,'0'));if(!Number.isSafeInteger(p)||p<=0)throw Error('Invalid amount.');return p;}
const bulkStatuses=['approved','awaiting_payment'];
let config,step=1,logoFile=null,coupon=null,couponInput='',freeRegistration=null,draft={category_id:'',institution:'',contact_name:'',email:'',phone:'',description:'',coupon_code:'',free_token:'',attendees:[]};
let submissionKey=sessionStorage.getItem('bc_submission_key')||uuid();sessionStorage.setItem('bc_submission_key',submissionKey);
const person=()=>({name:'',email:'',phone:'',designation:'',whatsapp_consent:false});
const category=()=>config.categories.find(c=>c.id===draft.category_id);
async function loadConfig(){config=await api('/categories');}
async function loadFreeRegistration(){const token=['/delegates','/exhibitors'].includes(path)?new URLSearchParams(location.hash.slice(1)).get('free')||'':'';if(!token)return;freeRegistration=await post('/free-registration/validate',{token});const expected=path==='/exhibitors'?'exhibitor':'delegate';if(freeRegistration.registration_kind!==expected)throw Error(`This complimentary link is for ${freeRegistration.registration_kind}s.`);draft.free_token=token;}
// Mirrors the server's discounted(): the offer price, rounded to the nearest rupee.
const offer=p=>coupon?Math.round(p*(100-coupon.percent_off)/10000)*100:p;
async function applyCoupon(code){code=code.trim().toUpperCase();coupon=null;draft.coupon_code='';if(!code)return;coupon=await post('/coupons',{code,category_id:draft.category_id});draft.coupon_code=coupon.code;couponInput=coupon.code;}
function capture(){const f=new FormData(document.getElementById('registration-form'));if(step===1){for(const k of ['category_id','institution','contact_name','email','phone','description'])if(f.has(k))draft[k]=String(f.get(k));const lf=f.get('logo');if(lf&&lf.size)logoFile=lf;if(f.has('coupon'))couponInput=String(f.get('coupon'));}if(step===2){draft.attendees=draft.attendees.map((p,i)=>({name:String(f.get(`name_${i}`)),email:String(f.get(`email_${i}`)),phone:String(f.get(`phone_${i}`)),designation:String(f.get(`designation_${i}`)),whatsapp_consent:f.has(`whatsapp_${i}`)}));if(category().kind==='delegate'){const p=draft.attendees[0];draft.contact_name=p.name;draft.email=p.email;draft.phone=p.phone;}}}
// Free links follow free_open; paid registration follows open.
const usable=c=>freeRegistration?c.free_open:c.open;
function formPage(){const kind=path==='/exhibitors'?'exhibitor':'delegate',cats=config.categories.filter(c=>c.kind===kind&&(!c.free_only||freeRegistration));if(!draft.category_id)draft.category_id=(kind==='delegate'?cats.find(c=>c.id==='industry'&&usable(c))?.id:'')||cats.find(usable)?.id||cats[0].id;const c=category();while(draft.attendees.length<c.roster_count)draft.attendees.push(person());draft.attendees.length=c.roster_count;
app.innerHTML=`<h1>${kind==='delegate'?'Be part of what comes next.':'Bring your ideas to the expo.'}</h1><p class="lede">${kind==='delegate'?'Two days of life sciences, ideas and connections.':'Register your institution and the people representing it.'}</p>${freeRegistration?`<div class="banner"><strong>Your registration is complimentary.</strong> Choose any ${kind} category and register for free through ${esc(freeRegistration.expires_on)}. ${freeRegistration.auto_approve?'Your registration is approved when you finish.':'Your registration will be sent to the organisers for review.'}</div>`:!config.registration_enabled?'<div class="banner"><strong>Registration opens soon.</strong> Review the form and fees below. Submissions are currently disabled.</div>':''}${usable(c)?'':`<div class="banner warning"><strong>${cats.some(usable)?'This category is closed.':'Registration is closed.'}</strong> ${cats.some(usable)?'Choose an open category to continue.':`New ${kind} registrations are not being accepted. Contact bioconnect@bio360.in for assistance.`}</div>`}<ol class="steps" aria-label="Registration progress">${['Your details',kind==='delegate'?'Your pass':'Attendees','Review & save'].map((s,i)=>`<li class="${step===i+1?'active':''}">${i+1}. ${s}</li>`).join('')}</ol><div class="layout"><section><form id="registration-form">${registrationStep(kind,cats)}<div class="actions">${step>1?'<button type="button" id="back" class="secondary">Back</button>':''}<button ${!usable(c)||step===3&&!freeRegistration&&!config.registration_enabled?'disabled':''}>${step===3?(freeRegistration?'Complete free registration':'Save registration & continue to payment'):'Continue'}</button></div></form></section><aside><h2>Your registration</h2><p>${esc(c.label)}</p>${freeRegistration?`<p class="price-was">${c.free_only?'':`<s>${money(c.payable_paise)}</s>`}Complimentary invitation</p>`:coupon?`<p class="price-was"><s id="published-fee">${money(c.payable_paise)}</s>${coupon.percent_off}% off with ${esc(coupon.code)}</p>`:''}<p class="price" id="current-fee">${freeRegistration?'Free':money(offer(c.payable_paise))}</p><small>${freeRegistration?(freeRegistration.auto_approve?'No payment is required. Your registration and passes are confirmed when you finish.':'No payment is required. The organisers will review your registration before issuing passes.'):coupon?'Offer price, paid by direct bank transfer. The account details appear once you save.':'Published fee payable in INR, subject to organiser confirmation against SBI.'}</small><hr class="divider"><p>${c.roster_count} attendee ${c.roster_count===1?'pass':'passes'}</p>${freeRegistration?`<small>This invitation is valid through ${esc(freeRegistration.expires_on)}.</small>`:'<small>Early-bird fees apply to verified payments through 30 September 2026, India time. Saving this form does not lock a fee.</small>'}${kind==='exhibitor'?(freeRegistration?'<p>Stall allocation remains subject to organiser confirmation.</p>':'<p>Stall allocation is manual. Confirm availability and allocation with organisers before paying. Payment does not guarantee a particular stall.</p>'):''}</aside></div>`;
bind('back','click',()=>{capture();step--;formPage();});bind('category','change',async()=>{capture();const code=coupon?.code;if(code&&category().coupon_eligible){try{await applyCoupon(code);}catch(err){couponInput='';formPage();throw err;}}else{coupon=null;draft.coupon_code='';couponInput='';}formPage();});bind('apply-coupon','click',async e=>{capture();if(!couponInput.trim())throw Error('Enter a coupon code.');await busy(e.target,()=>applyCoupon(couponInput),'Checking…');formPage();message(`Coupon applied: ${coupon.percent_off}% off.`);});bind('remove-coupon','click',()=>{capture();coupon=null;draft.coupon_code='';couponInput='';formPage();});bind('registration-form','submit',async e=>{e.preventDefault();capture();if(!category()||!usable(category()))throw Error('This category is closed. Choose an open category.');if(step===1&&couponInput.trim().toUpperCase()!==(coupon?.code||''))await applyCoupon(couponInput);if(step<3){step++;formPage();window.scrollTo({top:0,behavior:'smooth'});return;}await busy(e.submitter,async()=>{message('Saving registration. Please keep this page open.');let d;if(category().kind==='exhibitor'){if(!logoFile?.size)throw Error('Choose an institution logo.');const body=new FormData();body.append('payload',JSON.stringify(draft));body.append('logo',logoFile);const res=await fetch('/api/v1/registrations',{method:'POST',headers:{'Idempotency-Key':submissionKey},body});d=await res.json();if(!res.ok)throw Error(d.error||'Request failed. Please retry.');}else{d=await post('/registrations',draft,{'Idempotency-Key':submissionKey});}if(d.management_token){sessionStorage.removeItem('bc_submission_key');location.assign(`/manage/${d.id}#${d.management_token}`);}else message('This registration was already saved. Use the private link in your email or Recover registration.');});});}
function couponField(){const c=category();return `<div class="full"><div class="coupon"><label>Coupon code (optional)<input name="coupon" value="${esc(couponInput)}" maxlength="40" autocomplete="off" autocapitalize="characters" spellcheck="false" ${coupon?'readonly':''}></label>${coupon?'<button type="button" id="remove-coupon" class="secondary">Remove</button>':'<button type="button" id="apply-coupon" class="secondary">Apply</button>'}</div>${coupon?`<p class="help">${coupon.percent_off}% off applied. You pay ${money(offer(c.payable_paise))} by direct bank transfer; the account details appear once you save.</p>`:''}</div>`;}
function registrationStep(kind,cats){if(step===1)return `<div class="card"><h2>Institution & category</h2><div class="fields"><label class="full">Category<select name="category_id" id="category">${cats.map(c=>`<option value="${c.id}" ${draft.category_id===c.id?'selected':''} ${usable(c)?'':'disabled'}>${esc(c.label)}${usable(c)?'':' - closed'}</option>`).join('')}</select></label>${field('Institution','institution',draft.institution,'text','maxlength="180" autocomplete="organization"')}${kind==='exhibitor'?`${field('Contact person','contact_name',draft.contact_name,'text','maxlength="120"')}${field('Contact email','email',draft.email,'email')}${field('Contact phone (+country code)','phone',draft.phone,'tel','pattern="\\+[1-9][0-9]{7,14}"')}<label class="full">Company description<textarea name="description" required maxlength="3000">${esc(draft.description)}</textarea></label><label class="full">Institution logo (PNG or JPEG, up to 5 MB)<input type="file" name="logo" accept="image/png,image/jpeg" ${logoFile?'':'required'}></label>${logoFile?`<p class="help full">Selected: ${esc(logoFile.name)} - choose a file again only to replace it.</p>`:''}<p class="help full">The contact person receives a pass only if included in the attendee roster.</p>`:draft.category_id==='student'?'<p class="help">Students must present valid student ID at the registration desk.</p>':''}${!freeRegistration&&category().coupon_eligible?couponField():''}</div></div>`;
if(step===2)return `<p>Provide exactly ${category().roster_count} ${kind==='delegate'?'attendee':'attendees'}. Each receives an individual pass ${freeRegistration?.auto_approve?'when registration is complete':'after approval'}.</p>${draft.attendees.map((p,i)=>`<fieldset><legend>Attendee ${i+1}</legend><div class="fields">${field('Full name',`name_${i}`,p.name,'text','maxlength="120"')}${field('Designation',`designation_${i}`,p.designation,'text','maxlength="180"')}${field('Email',`email_${i}`,p.email,'email')}${field('Phone (e.g. +919876543210)',`phone_${i}`,p.phone,'tel','pattern="\\+[1-9][0-9]{7,14}"')}</div><label class="check"><input type="checkbox" name="whatsapp_${i}" ${p.whatsapp_consent?'checked':''}>I have permission to send this attendee their Bio Connect 4.0 pass and delivery updates by WhatsApp.</label><p class="help">Optional. Their pass will still be sent by email.</p></fieldset>`).join('')}`;
return `<div class="card"><h2>Review your registration</h2>${pairs([['Category',category().label],...(freeRegistration?[['Registration fee','Free']]:coupon?[['Coupon',`${coupon.code} - ${coupon.percent_off}% off`],['Offer price',`${money(offer(category().payable_paise))} by bank transfer`]]:[]),['Institution',draft.institution],['Contact',draft.contact_name],['Email',draft.email],['Phone',draft.phone],...(kind==='exhibitor'?[['Description',draft.description],['Institution logo',logoFile?logoFile.name:'not selected']]:[])])}<hr class="divider"><h3>Attendees</h3>${draft.attendees.map(p=>`<p><strong>${esc(p.name)}</strong><br>${esc(p.designation)} · ${esc(p.email)}<br>${esc(p.phone)} · WhatsApp ${p.whatsapp_consent?'permitted':'not permitted'}</p>`).join('')}<label class="check"><input type="checkbox" required>I have checked these details and have permission to provide the attendees’ information for registration and pass delivery.</label><p class="help">We use these details for registration, payment review and pass delivery. Contact bioconnect@bio360.in for assistance or corrections. No attendee account is created.</p></div>`;}
async function upload(rid,kind,file,headers,base='/api/v1/registrations'){if(!file?.size)throw Error('Choose a file.');if(file.size>5*1024*1024)throw Error('Files must be 5 MB or smaller.');const url=`${base}/${rid}/files?kind=${kind}`,res=await fetch(url,{method:'POST',headers:{...headers,'Content-Type':'application/octet-stream'},body:file});await checkStaffResponse(res,url.replace('/api/v1',''));const out=await res.json();if(!res.ok)throw Error(out.error||'Upload failed. Retry with the same registration.');return out;}
// Open places are passes an exhibitor's allowance grants but no attendee holds yet, left by an allowance rise.
function openPlaces(d){const r=d.registration;return d.category.kind==='exhibitor'&&!['rejected','cancelled'].includes(r.status)?r.roster_count-r.attendees.length:0;}
function assigned(d){const r=d.registration;return d.category.kind==='exhibitor'?[['Stall',r.stall_number||'To be allocated'],['Passes',`${r.attendees.length} of ${r.roster_count} assigned`]]:[];}
function attendeeForm(d,staff=false){const r=d.registration,open=openPlaces(d);if(open<1)return '';return `<form id="attendee-form" class="card"><h2>${staff?'Add an attendee':'Add your team'}</h2><p>${staff?`${open} of this registration's ${r.roster_count} passes ${open===1?'is':'are'} not yet assigned.`:`Your stall now includes ${r.roster_count} passes at no extra cost. ${open} ${open===1?'is':'are'} not yet assigned.`} ${r.status==='approved'?(staff?'The pass is issued at once but not sent. Send it from the attendee list when ready.':'Each person you add receives their own pass straight away.'):'Passes are issued after approval.'} Passes already issued stay valid.</p><div class="fields">${field('Full name','name','','text','maxlength="120"')}${field('Designation','designation','','text','maxlength="180"')}${field('Email','email','','email')}${field('Phone (e.g. +919876543210)','phone','','tel','pattern="\\+[1-9][0-9]{7,14}"')}</div><label class="check"><input type="checkbox" name="whatsapp_consent">I have permission to send this attendee their Bio Connect 4.0 pass and delivery updates by WhatsApp.</label><p class="help">Optional. Their pass will still be sent by email.</p><div class="actions"><button>Add attendee</button></div></form>`;}
function attendeeBody(form){const f=new FormData(form);return {name:f.get('name'),designation:f.get('designation'),email:f.get('email'),phone:f.get('phone'),whatsapp_consent:f.has('whatsapp_consent')};}
async function managePage(){const rid=path.split('/')[2];if(location.hash){sessionStorage.setItem('bc_manage_'+rid,location.hash.slice(1));history.replaceState(null,'',path);}const token=sessionStorage.getItem('bc_manage_'+rid)||'',headers={Authorization:'Bearer '+token};if(!token){app.innerHTML='<h1>Recover your registration.</h1><p>Use your private management link or <a href="/recover">request a recovery email</a>.</p>';return;}const d=await api('/registrations/'+rid,{headers}),r=d.registration,c=d.category;const owing=['awaiting_payment','correction_requested'].includes(r.status);
app.innerHTML=`<div class="single"><h1>Your registration is saved.</h1><p><span class="pill">${esc(r.status.replaceAll('_',' '))}</span> <strong class="mono">${esc(r.reference)}</strong></p>${r.review_note?`<div class="banner warning"><strong>Organiser note</strong><p>${esc(r.review_note)}</p></div>`:''}${owing?payCallout(d,r,c)+paymentForm(d):`<div class="banner">${r.status==='awaiting_review'?(r.free_registration?'Your complimentary registration is awaiting organiser review. There is no payment to make. Your pass will be delivered after approval.':'Your payment evidence is with the organisers for bank verification.'):r.status==='approved'?(r.free_registration?'Your complimentary registration is confirmed. There is no payment to make. Passes are delivered separately to attendees.':'Your registration is approved. Passes are delivered separately to attendees. Contact organisers for a resend.'):'Contact bioconnect@bio360.in for assistance.'}</div>`}${attendeeForm(d)}<div class="card"><h2>${esc(r.institution)}</h2>${pairs([['Contact',r.contact_name],['Email',r.email],['Category',c.label],...assigned(d),...(r.free_registration?[['Registration fee','Free']]:r.coupon_code?[['Coupon',`${r.coupon_code} - ${r.discount_percent}% off`]]:[]),...(owing?[]:r.free_registration?[]:[['Current fee',money(d.payable_paise)]]),['Saved on',date(r.created_at)]])}<details><summary>Attendee details</summary>${table(r.attendees,[['name','Name'],['designation','Designation'],['email','Email'],['phone','Phone']])}</details><div class="actions"><button id="copy-return" class="secondary" type="button">Copy secure return link</button></div><p class="help">Keep this link private. It reopens your registration without a password.</p></div>${r.free_registration?'':`<div class="card"><h2>Payment history</h2>${table(d.payments.map(p=>({...p,payment_date:date(p.payment_date),amount:money(p.amount_paise)})),[['bank_reference','Reference'],['payment_date','Date'],['amount','Reported amount'],['verified_at','Verified at']])}</div>`}</div>`;
bind('copy-return','click',async()=>{await navigator.clipboard.writeText(location.origin+'/manage/'+rid+'#'+token);message('Private return link copied. Keep it secure.');});bind('payment-form','submit',async e=>{e.preventDefault();await busy(e.submitter,async()=>{const f=new FormData(e.target);message('Submitting evidence. Your registration is already saved.');if(f.get('logo')?.size)await upload(rid,'logo',f.get('logo'),headers);await post(`/registrations/${rid}/payments`,{reference:f.get('reference'),date:f.get('date'),amount_paise:paise(f.get('amount'))},headers);message('Payment evidence submitted for manual review.');await managePage();});});bind('attendee-form','submit',async e=>{e.preventDefault();await busy(e.submitter,async()=>{await post(`/registrations/${rid}/attendees`,attendeeBody(e.target),headers);message(r.status==='approved'?'Attendee added. Their pass is on its way.':'Attendee added. Their pass is issued after approval.');await managePage();});});}
function payCallout(d,r,c){const amount=money(d.payable_paise),primary=r.status==='awaiting_payment';if(d.bank_transfer)return bankCallout(d,r,c,amount,primary);return `<div class="card pay-card"><h2>${primary?'Pay your registration fee':'Payment details'}</h2><p class="pay-amount">${amount}<span>Current fee &middot; ${esc(c.label)}</span></p>${d.sbi_url?`<div class="actions"><a class="button ${primary?'pay-cta':'secondary'}" href="${esc(d.sbi_url)}" target="_blank" rel="noopener noreferrer">${primary?`Pay ${amount} at SBI`:'Pay at SBI'}</a></div>`:'<div class="banner warning"><strong>The SBI payment link is awaiting organiser confirmation.</strong> Do not pay until the link appears here.</div>'}<p class="help">${primary?'Opens SBI in a new tab.':'Pay again only if the organisers have asked you to.'} Quote reference <strong class="mono">${esc(r.reference)}</strong> where SBI supports it, and note your SBI reference, payment date and amount for the form below. An SBI receipt or redirect does not approve your registration.</p><p class="help">Verified payments through 30 September 2026 qualify for early-bird fees, even if evidence is submitted later.</p>${c.kind==='exhibitor'?'<p class="help">Confirm availability and manual stall allocation with organisers before paying. Payment does not guarantee a particular stall.</p>':''}</div>`;}
function bankCallout(d,r,c,amount,primary){const b=d.bank_transfer;return `<div class="card pay-card"><h2>${primary?'Pay your registration fee':'Payment details'}</h2><p class="pay-amount">${amount}<span>Offer price with ${esc(r.coupon_code)} &middot; ${esc(c.label)}</span></p><h3>Bank transfer details</h3>${pairs([['Account name',b.account_name],['Bank',b.bank],['Branch',b.branch],['Account number',b.account_number],['IFSC',b.ifsc]])}<p class="help">${primary?`Transfer exactly ${amount} by NEFT, RTGS or IMPS.`:'Transfer again only if the organisers have asked you to.'} Quote reference <strong class="mono">${esc(r.reference)}</strong> in the transfer remarks, and note the transaction reference (UTR), date and amount for the form below. A bank confirmation does not approve your registration.</p><p class="help">Verified payments through 30 September 2026 qualify for early-bird fees, even if evidence is submitted later.</p>${c.kind==='exhibitor'?'<p class="help">Confirm availability and manual stall allocation with organisers before paying. Payment does not guarantee a particular stall.</p>':''}</div>`;}
function paymentForm(d){return `<form id="payment-form" class="card"><h2>Submit payment evidence</h2><p>${d.bank_transfer?'Only submit after completing the bank transfer.':'Only submit after paying through the confirmed SBI setup.'} Staff verify the payment, beneficiary, reference, date and amount against the bank's reconciliation report.</p><div class="fields">${field(d.bank_transfer?'Transaction reference (UTR)':'Bank transaction reference','reference','','text','maxlength="100"')}${field('Payment date (India time)','date','','date')}${field('Amount paid in INR','amount',((d.payable_paise||0)/100).toFixed(2),'number','min="0.01" step="0.01"')}${d.category.kind==='exhibitor'?`<label class="full">Institution logo ${d.files.some(f=>f.kind==='logo')?'(uploaded &#10003; &ndash; choose a file only to replace it)':'(PNG or JPEG, up to 5 MB &ndash; required)'}<input type="file" name="logo" accept="image/png,image/jpeg" ${d.files.some(f=>f.kind==='logo')?'':'required'}></label>`:''}</div><p class="help">The amount is prefilled with ${d.bank_transfer?'your offer price':'the current fee'}. Change it only if you paid a different amount.</p><div class="actions"><button>Submit for review</button></div></form>`;}
async function recoveryPage(){const token=location.hash.slice(1);history.replaceState(null,'',path);if(token){app.innerHTML='<div class="single"><h1>Open your registration.</h1><p>Continue to view your registration, add attendees or submit payment details.</p><div class="actions"><button id="exchange">Continue to my registration</button></div><p class="help">This private link works once. After you continue, use <strong>Copy secure return link</strong> on your registration to come back later; earlier links to your registration stop working.</p><p class="help">Link already used or expired? <a href="/recover">Request a new one by email</a>.</p></div>';bind('exchange','click',async e=>busy(e.target,async()=>{const d=await post('/recovery/exchange',{token});location.assign(`/manage/${d.id}#${d.management_token}`);}));return;}app.innerHTML=`<div class="account"><h1>Pick up where you left off.</h1><p>Enter the registration contact email for a private link valid for 20 minutes.</p><form id="recover" class="card">${field('Contact email','email','','email')}<div class="actions"><button>Send recovery link</button></div></form></div>`;bind('recover','submit',async e=>{e.preventDefault();await busy(e.submitter,async()=>message((await post('/recovery',{email:new FormData(e.target).get('email')})).message));});}
let filters=new URLSearchParams(),listing,me,listSeq=0,listAbort,searchTimer,routed=false,searchKey=false;
function checkStaffCookie(){if(me&&!csrf())endStaffSession();}
if(path==='/admin'){setInterval(checkStaffCookie,30000);addEventListener('focus',checkStaffCookie);document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkStaffCookie();});}
const statuses=['awaiting_payment','awaiting_review','correction_requested','approved','rejected','cancelled'],pageSizes=['25','50','100'],statusName=s=>String(s).replaceAll('_',' ');
// The list's filters, page and page size live in the address bar, so a reload,
// a shared link or Back from a registration returns to exactly the same view.
// Filter and page changes replace the entry; only opening a registration adds one.
function listParams(){const p=new URLSearchParams(location.search);p.delete('registration');return p;}
function setListURL(p){const q=p.toString();history.replaceState(history.state,'',q?'?'+q:location.pathname);}
async function adminPage(){try{me=await api('/admin/me');}catch{loginPage();return;}if(!routed){routed=true;addEventListener('popstate',()=>adminRoute(history.state?.scroll).catch(e=>message(e.message,true)));}await adminRoute();}
async function adminRoute(scroll){if(!me)return loginPage();if(['mobile','event-guide'].includes(new URLSearchParams(location.search).get("view")))return mobileContentPage();if(me.role==='manager')return accountsPage();const id=new URLSearchParams(location.search).get('registration');if(id)return adminDetail(id,{top:true});await adminList();if(scroll)window.scrollTo({top:scroll});}
function backToList(){if(history.state?.fromList){history.back();return;}setListURL(listParams());return adminList();}
function loginPage(){me=null;app.innerHTML=`<div class="account"><h1>Staff sign in.</h1><p>Use your individual account and authenticator code.</p><form id="login" class="card">${field('Email','email','','email','autocomplete="username"')}${field('Password','password','','password','autocomplete="current-password"')}${field('Authenticator code','code','','text','inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code"')}<div class="actions"><button>Sign in</button></div></form></div>`;if(sessionStorage.getItem('bc_staff_session_ended')){sessionStorage.removeItem('bc_staff_session_ended');message('Your staff session has ended. Please sign in again.');}bind('login','submit',async e=>{e.preventDefault();await busy(e.submitter,async()=>{await post('/auth/login',Object.fromEntries(new FormData(e.target)));await adminPage();},'Signing in…');});}
function logout(){bind('logout','click',async e=>busy(e.target,async()=>{await post('/admin/logout',{});loginPage();},'Signing out…'));}
function summaryPanel(cats){return `<section id="summary" class="admin-summary" aria-label="Registration overview">${[['delegate','Delegates'],['exhibitor','Exhibitors']].map(([kind,title])=>{const rows=cats.filter(c=>c.kind===kind),reg=rows.reduce((n,c)=>n+c.registered,0),ok=rows.reduce((n,c)=>n+c.confirmed,0);return `<div class="summary-group"><div class="summary-head"><h2>${title}</h2><p class="summary-total"><span><strong>${reg}</strong> registered</span><span><strong>${ok}</strong> confirmed</span></p></div><ul class="summary-rows">${rows.map(c=>`<li><span class="summary-label">${esc(c.label)}</span><progress class="summary-meter" aria-hidden="true" max="${c.registered||1}" value="${c.confirmed}"></progress><span class="summary-count"><strong>${c.confirmed}</strong> / ${c.registered}<span class="sr-only"> confirmed of registered</span></span></li>`).join('')}</ul></div>`;}).join('')}</section>`;}
// Widths are classes because the CSP refuses inline styles.
const skeleton=(w=100)=>`<span class="skeleton w${w}"></span>`;
function summarySkeleton(){return `<section id="summary" class="admin-summary" aria-busy="true" aria-label="Loading registration overview">${[0,1].map(()=>`<div class="summary-group"><div class="summary-head">${skeleton(30)}${skeleton(40)}</div><ul class="summary-rows">${[70,55,60,50].map(w=>`<li>${skeleton(w)}</li>`).join('')}</ul></div>`).join('')}</section>`;}
function skeletonRows(n=8){return Array.from({length:n},(_,i)=>`<tr class="skeleton-row" aria-hidden="true"><td class="select-column">${skeleton('box')}</td><td>${skeleton(80)}</td><td>${skeleton([75,60,85][i%3])}${skeleton(45)}</td><td>${skeleton(60)}</td><td>${skeleton(70)}</td><td>${skeleton(80)}</td></tr>`).join('');}
function tableHead(){return `<thead><tr><th class="select-column"><input type="checkbox" id="select-all" aria-label="Select all approved and awaiting-payment registrations on this page" disabled></th><th>Reference</th><th>Institution / contact</th><th>Category</th><th>Status</th><th>Created</th></tr></thead>`;}
// category_id arrives as "startup" or "startup · Free link".
function categoryName(v){const [id,...rest]=String(v).split(' · ');return [config.categories.find(c=>c.id===id)?.label||id,...rest].join(' · ');}
function statusTabs(counts){const all=counts?Object.values(counts).reduce((n,v)=>n+v,0):null,current=filters.get('status')||'';return [['','All',all],...statuses.map(s=>[s,statusName(s),counts?counts[s]||0:null])].map(([s,label,n])=>`<button type="button" class="status-tab${s?' status-tab-'+s.replaceAll('_','-'):''}${n===0?' is-empty':''}" data-status="${s}" aria-pressed="${current===s}">${esc(label)}${n===null?'':`<span class="status-tab-count">${n}</span>`}</button>`).join('');}
const filterLabels={q:'Search',category:'Category',from:'From',to:'Through'};
function chipValue(k,v){return k==='category'?config.categories.find(c=>c.id===v)?.label||v:k==='from'||k==='to'?day(v+'T00:00:00+05:30'):`“${v}”`;}
function renderChips(){const el=document.getElementById('active-filters'),active=Object.keys(filterLabels).filter(k=>filters.get(k));if(filters.get('status'))active.push('status');el.hidden=!active.length;el.innerHTML=active.length?`<span class="chips-label">Filtered by</span>${active.map(k=>`<span class="chip">${k==='status'?`Status: ${esc(statusName(filters.get(k)))}`:`${filterLabels[k]}: ${esc(chipValue(k,filters.get(k)))}`}<button type="button" class="chip-remove" data-key="${k}" aria-label="Remove ${k==='status'?'status':filterLabels[k].toLowerCase()} filter">&times;</button></span>`).join('')}<button type="button" id="clear-filters" class="quiet">Clear all</button>`:'';}
// First, last, and the neighbours of the current page, with a gap wherever
// pages are skipped; a gap of exactly one page shows that page instead.
function pageNumbers(cur,total){const keep=new Set([1,total,cur-1,cur,cur+1].filter(n=>n>=1&&n<=total)),out=[];let last=0;for(const n of [...keep].sort((a,b)=>a-b)){if(n-last===2)out.push(last+1);else if(n-last>2)out.push('gap');out.push(n);last=n;}return out;}
function pagination(){const {page,pages,total,page_size:size}=listing;if(!total)return '';const first=(page-1)*size+1,last=Math.min(page*size,total);return `<p class="pagination-range">Showing <strong>${first}&ndash;${last}</strong> of <strong>${total}</strong></p><div class="pagination-pages">${pages>1?`<button type="button" class="page-step secondary" data-page="${page-1}" ${page===1?'disabled':''} aria-label="Previous page"><span aria-hidden="true">&larr;</span> Prev</button><ol class="page-numbers">${pageNumbers(page,pages).map(n=>n==='gap'?'<li class="page-gap" aria-hidden="true">&hellip;</li>':`<li><button type="button" class="page-number" data-page="${n}" ${n===page?'aria-current="page"':''} aria-label="Page ${n}">${n}</button></li>`).join('')}</ol><span class="page-compact">Page ${page} of ${pages}</span><button type="button" class="page-step secondary" data-page="${page+1}" ${page===pages?'disabled':''} aria-label="Next page">Next <span aria-hidden="true">&rarr;</span></button>`:`<span class="page-single">Page 1 of 1</span>`}</div><label class="page-size">Rows per page<select id="page-size">${pageSizes.map(s=>`<option ${String(size)===s?'selected':''}>${s}</option>`).join('')}</select></label>`;}
function exportQuery(){const p=new URLSearchParams(filters);p.delete('page');p.delete('page_size');return p;}
function renderResults(){const box=document.getElementById('results'),{items,total,page,pages}=listing,filtered=[...filters.keys()].some(k=>k in filterLabels||k==='status');
document.getElementById('status-tabs').innerHTML=statusTabs(listing.status_counts);
document.getElementById('result-count').innerHTML=total?`<strong>${total}</strong> registration${total===1?'':'s'}<span>Page ${page} of ${pages}</span>`:'<strong>0</strong> registrations';
document.getElementById('xlsx').href='/api/v1/admin/export?'+exportQuery()+'&format=xlsx';
box.innerHTML=`<table class="admin-table">${tableHead()}<tbody>${items.map(r=>`<tr><td class="select-column"><input type="checkbox" aria-label="Select ${esc(r.reference)}" class="select-reg" value="${r.id}" data-status="${esc(r.status)}" ${bulkStatuses.includes(r.status)?'':'disabled'}></td><td><button type="button" class="open-reg reference-button" data-id="${r.id}">${esc(r.reference)}</button></td><td><strong class="institution-name">${esc(r.institution)}</strong><span class="contact-detail">${esc(r.contact_name)}</span><a class="contact-detail" href="mailto:${esc(r.email)}">${esc(r.email)}</a></td><td><span class="category-label">${esc(categoryName(r.category_id))}</span></td><td><span class="status status-${esc(r.status.replaceAll('_','-'))}">${esc(statusName(r.status))}</span></td><td class="created-date">${date(r.created_at)}</td></tr>`).join('')||`<tr><td class="admin-empty" colspan="6"><strong>${filtered?'No registrations match these filters.':'No registrations yet.'}</strong>${filtered?'<span>Try a different search or status, or clear the filters.</span><button type="button" id="empty-clear" class="secondary">Clear filters</button>':'<span>New registrations appear here as soon as they are submitted.</span>'}</td></tr>`}</tbody>`;
document.getElementById('select-all').disabled=!items.some(r=>bulkStatuses.includes(r.status));
document.getElementById('pagination').innerHTML=pagination();updateSelection();}
function updateSelection(){const selections=[...document.querySelectorAll('.select-reg:not(:disabled)')],selectAll=document.getElementById('select-all'),selected=selections.filter(el=>el.checked).length,sends=picked('approved').length,reminders=picked('awaiting_payment').length,bulk=document.getElementById('bulk'),remind=document.getElementById('bulk-remind');bulk.disabled=!sends;bulk.textContent=sends?`Send passes (${sends})`:'Send passes';remind.disabled=!reminders;remind.textContent=reminders?`Remind to pay (${reminders})`:'Remind to pay';if(selectAll){selectAll.checked=selected===selections.length&&selected>0;selectAll.indeterminate=selected>0&&selected<selections.length;}}
const picked=status=>[...document.querySelectorAll('.select-reg:checked')].filter(el=>el.dataset.status===status).map(el=>el.value);
// Keeps the rows on screen, dimmed, while the next set loads, and drops any
// response that a newer filter or page change has already superseded.
async function loadResults({toTop=false,searching=false}={}){const seq=++listSeq,box=document.getElementById('results');listAbort?.abort();listAbort=new AbortController();renderChips();document.querySelectorAll('.status-tab').forEach(el=>el.setAttribute('aria-pressed',String((filters.get('status')||'')===el.dataset.status)));if(!box.querySelector('table'))box.innerHTML=`<table class="admin-table">${tableHead()}<tbody>${skeletonRows()}</tbody></table>`;box.classList.add('is-loading');box.setAttribute('aria-busy','true');document.getElementById('admin-search')?.classList.toggle('is-searching',searching);
try{const out=await api('/admin/registrations?'+filters,{signal:listAbort.signal});if(seq!==listSeq)return;if(out.pages&&out.page>out.pages){filters.set('page',out.pages);setListURL(filters);return loadResults({toTop});}listing=out;renderResults();if(toTop)document.getElementById('results-top').scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
catch(e){if(e.name==='AbortError'||seq!==listSeq)return;box.innerHTML=`<div class="admin-error" role="alert"><strong>Registrations could not be loaded.</strong><span>${esc(e.message)}</span><button type="button" id="retry-list" class="secondary">Try again</button></div>`;document.getElementById('result-count').textContent='';document.getElementById('pagination').innerHTML='';}
finally{if(seq===listSeq){box.classList.remove('is-loading');box.removeAttribute('aria-busy');document.getElementById('admin-search')?.classList.remove('is-searching');}}}
async function loadSummary(){const el=document.getElementById('summary');try{const s=await api('/admin/summary');if(el.isConnected)el.outerHTML=summaryPanel(s.categories);}catch(e){if(el.isConnected)el.outerHTML=`<section id="summary" class="admin-summary"><p class="admin-error" role="alert"><strong>Overview unavailable.</strong><span>${esc(e.message)}</span></p></section>`;}}
function setFilter(key,value){value?filters.set(key,value):filters.delete(key);filters.delete('page');setListURL(filters);return loadResults();}
// Filters apply as they change; typing waits for a pause, and Enter applies at once.
function applyForm(form){clearTimeout(searchTimer);const f=new FormData(form),from=f.get('from'),to=form.elements.to;to.setCustomValidity(from&&to.value&&from>to.value?'Through date must be on or after the From date.':'');if(!to.checkValidity()){to.reportValidity();return;}const next=new URLSearchParams();for(const [k,v] of f)if(String(v).trim())next.set(k,String(v).trim());for(const k of ['status','page_size'])if(filters.get(k))next.set(k,filters.get(k));const same=new URLSearchParams(filters);same.delete('page');next.sort();same.sort();if(next.toString()===same.toString())return;const searching=next.get('q')!==filters.get('q');filters=next;setListURL(filters);return loadResults({searching});}
function clearFilters(){const form=document.getElementById('filters');for(const k of Object.keys(filterLabels))form.elements[k].value='';const size=filters.get('page_size');filters=new URLSearchParams(size?{page_size:size}:{});setListURL(filters);return loadResults();}
async function adminList(){filters=listParams();app.innerHTML=`<div class="admin-page"><header class="admin-heading"><div><p class="admin-kicker">Staff console</p><h1>Registrations</h1><p class="admin-intro">Review payments, approve registrations and manage pass delivery.</p></div><div class="admin-header-actions"><button id="new-registration">New registration</button><button id="refresh" class="secondary">Refresh</button><button id="free-links" class="secondary">Free link</button><button id="categories" class="secondary">Manage categories</button><button id="mobile-app" class="secondary">Mobile app</button><button id="posters" class="secondary">Social posters</button><button id="logout" class="quiet">Sign out</button></div></header>${summarySkeleton()}<form id="filters" class="admin-filters" role="search"><h2 class="sr-only">Filter registrations</h2><label class="admin-search" id="admin-search">Search<span class="search-field"><input name="q" value="${esc(filters.get('q')||'')}" type="search" placeholder="Reference, institution, attendee or pass number" autocomplete="off" aria-keyshortcuts="/"><span class="search-spinner" aria-hidden="true"></span></span></label><label>From<input name="from" value="${esc(filters.get('from')||'')}" type="date"></label><label>Through<input name="to" value="${esc(filters.get('to')||'')}" type="date"></label><label>Category<select name="category"><option value="">All categories</option>${config.categories.map(c=>`<option value="${c.id}" ${filters.get('category')===c.id?'selected':''}>${esc(c.label)}</option>`).join('')}</select></label></form><div id="status-tabs" class="status-tabs" role="group" aria-label="Filter by status">${statusTabs()}</div><div id="active-filters" class="active-filters" hidden></div><div id="results-top" class="admin-toolbar"><p id="result-count" class="admin-result-count" aria-live="polite">${skeleton('count')}</p><div class="admin-export"><label>CSV data<select id="csv-sheet">${['Registrations','Attendees','Payments','Deliveries'].map(s=>`<option>${s}</option>`).join('')}</select></label><button id="csv" class="secondary">Export CSV</button><a id="xlsx" class="button secondary" href="/api/v1/admin/export?${esc(exportQuery())}&format=xlsx">Export XLSX</a></div></div><div class="admin-bulk"><p><strong>Bulk actions</strong><span>Select approved registrations to send passes, or awaiting-payment ones to remind them to pay.</span></p><div class="admin-bulk-actions"><button id="bulk" disabled>Send passes</button><button id="bulk-remind" class="secondary" disabled>Remind to pay</button></div></div><p class="table-hint">Swipe sideways to view all columns <span aria-hidden="true">&rarr;</span></p><div id="results" class="table-scroll admin-table-wrap"></div><nav id="pagination" class="admin-pagination" aria-label="Registration pages"></nav></div>`;
const form=document.getElementById('filters'),box=document.getElementById('results');logout();
form.addEventListener('submit',e=>{e.preventDefault();applyForm(form);});form.addEventListener('change',e=>{if(e.target.name!=='q')applyForm(form);});form.elements.q.addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>applyForm(form),350);});
document.getElementById('status-tabs').addEventListener('click',e=>{const tab=e.target.closest('.status-tab');if(tab&&tab.getAttribute('aria-pressed')!=='true')setFilter('status',tab.dataset.status);});
document.getElementById('active-filters').addEventListener('click',e=>{if(e.target.id==='clear-filters')return clearFilters();const k=e.target.closest('.chip-remove')?.dataset.key;if(!k)return;if(k!=='status')form.elements[k].value='';setFilter(k,'');});
document.getElementById('pagination').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(!b||b.disabled||b.hasAttribute('aria-current'))return;filters.set('page',b.dataset.page);setListURL(filters);loadResults({toTop:true});});
document.getElementById('pagination').addEventListener('change',e=>{if(e.target.id!=='page-size')return;e.target.value==='25'?filters.delete('page_size'):filters.set('page_size',e.target.value);filters.delete('page');setListURL(filters);loadResults({toTop:true});});
box.addEventListener('click',e=>{if(e.target.id==='retry-list')return loadResults();if(e.target.id==='empty-clear')return clearFilters();const b=e.target.closest('.open-reg');if(b)openRegistration(b);});
box.addEventListener('change',e=>{if(e.target.id==='select-all')document.querySelectorAll('.select-reg:not(:disabled)').forEach(el=>el.checked=e.target.checked);updateSelection();});
bind('refresh','click',async e=>busy(e.target,()=>Promise.all([loadSummary(),loadResults()]),'Refreshing…'));
bind('csv','click',()=>location.assign('/api/v1/admin/export?'+exportQuery()+'&format=csv&sheet='+document.getElementById('csv-sheet').value));
const report=out=>message(Object.entries(out).map(([id,s])=>`${listing.items.find(r=>r.id===id)?.reference}: ${s}`).join('; '));
bind('bulk','click',async e=>busy(e.target,async()=>report(await post('/admin/bulk-send',{ids:picked('approved'),channel:''})),'Sending…'));
bind('bulk-remind','click',async e=>{const ids=picked('awaiting_payment');if(!confirm(`Email a payment reminder to ${ids.length} registration${ids.length===1?'':'s'}?`))return;await busy(e.target,async()=>report(await post('/admin/bulk-remind',{ids})),'Sending…');});
bind('new-registration','click',e=>busy(e.target,staffRegistrationPage,'Opening…'));bind('free-links','click',e=>busy(e.target,()=>freeLinksPage(),'Opening…'));bind('categories','click',e=>busy(e.target,categoryAdmin,'Opening…'));bind('posters','click',e=>busy(e.target,()=>posterHome(),'Opening…'));bind('mobile-app','click',e=>busy(e.target,()=>{history.pushState(null,'','/admin?view=mobile');return mobileContentPage();},'Opening…'));
if(!searchKey){searchKey=true;document.addEventListener('keydown',e=>{const q=document.querySelector('#filters input[name=q]');if(e.key==='/'&&q&&!e.target.closest('input,select,textarea,[contenteditable]')){e.preventDefault();q.focus();q.select();}});}
await Promise.all([loadSummary(),loadResults()]);}
async function openRegistration(button){message('');button.classList.add('is-busy');button.setAttribute('aria-busy','true');document.getElementById('results').classList.add('is-loading');try{await adminDetail(button.dataset.id,{push:true});}catch(e){message(e.message,true);}finally{button.classList.remove('is-busy');button.removeAttribute('aria-busy');document.getElementById('results')?.classList.remove('is-loading');}}

// Staff registration: one form for every delegate and exhibitor category,
// confirmed on save as paid (verified bank payment) or complimentary. The
// draft survives re-renders when the category or payment choice changes.
let staffDraft=null,staffLogo=null;
const staffFields=['category_id','institution','contact_name','email','phone','description','payment','verified_reference','verified_date','amount','coupon_code','note'];
function optField(label,name,value='',type='text',extra=''){return `<label>${esc(label)}<input name="${esc(name)}" value="${esc(value)}" type="${type}" ${extra}></label>`;}
function staffCategory(){return config.categories.find(c=>c.id===staffDraft.category_id)||config.categories[0];}
function staffCapture(form){const f=new FormData(form),d=staffDraft;for(const k of staffFields)if(f.has(k))d[k]=String(f.get(k));d.attendees=d.attendees.map((p,i)=>f.has(`name_${i}`)?{name:String(f.get(`name_${i}`)),designation:String(f.get(`designation_${i}`)),email:String(f.get(`email_${i}`)),phone:String(f.get(`phone_${i}`)),whatsapp_consent:f.has(`whatsapp_${i}`)}:p);const logo=f.get('logo');if(logo?.size)staffLogo=logo;}
function staffAttendee(p,i,kind){const need=i===0,req=need?'required':'';return `<fieldset><legend>${kind==='delegate'?'Attendee':`Attendee ${i+1}${i?' - optional':''}`}</legend><div class="fields">${optField('Full name',`name_${i}`,p.name,'text',`maxlength="120" ${req}`)}${optField('Designation',`designation_${i}`,p.designation,'text',`maxlength="180" ${req}`)}${optField('Email',`email_${i}`,p.email,'email',req)}${optField('Phone (optional, e.g. +919876543210)',`phone_${i}`,p.phone,'tel','pattern="\\+[1-9][0-9]{7,14}"')}</div><label class="check"><input type="checkbox" name="whatsapp_${i}" ${p.whatsapp_consent?'checked':''}>Send this attendee's pass by WhatsApp too (needs a phone number).</label>${need?'':'<p class="help">Leave blank to fill this place later.</p>'}</fieldset>`;}
async function staffRegistrationPage(){await loadConfig();if(!staffDraft){staffDraft={category_id:'industry',institution:'',contact_name:'',email:'',phone:'',description:'',payment:'complimentary',verified_reference:'',verified_date:'',amount:'',coupon_code:'',note:'',attendees:[],key:uuid()};staffLogo=null;}const d=staffDraft,c=staffCategory(),kind=c.kind,today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata'}).format(new Date());while(d.attendees.length<c.roster_count)d.attendees.push(person());d.attendees.length=c.roster_count;if(c.free_only)d.payment='complimentary';const paid=d.payment==='paid',group=k=>config.categories.filter(x=>x.kind===k).map(x=>`<option value="${x.id}" ${x.id===c.id?'selected':''}>${esc(x.label)}${x.free_only?' - complimentary only':''}</option>`).join('');
app.innerHTML=`<button id="return" class="secondary back-button"><span aria-hidden="true">&larr;</span> Back to registrations</button><h1>New registration.</h1><p>Register a delegate or exhibitor on their behalf. The registration is confirmed when you save it, whether or not public registration or the category is open. Nothing is emailed unless you choose to send the passes.</p><form id="staff-registration" class="card"><h2>Details</h2><div class="fields"><label class="full">Category<select name="category_id" id="staff-category"><optgroup label="Delegates">${group('delegate')}</optgroup><optgroup label="Exhibitors">${group('exhibitor')}</optgroup></select></label><label class="full">Institution<input name="institution" value="${esc(d.institution)}" maxlength="180" autocomplete="organization" required></label>${kind==='exhibitor'?`${field('Contact person','contact_name',d.contact_name,'text','maxlength="120"')}${field('Contact email','email',d.email,'email')}${optField('Contact phone (optional, +country code)','phone',d.phone,'tel','pattern="\\+[1-9][0-9]{7,14}"')}<label class="full">Company description<textarea name="description" required maxlength="3000">${esc(d.description)}</textarea></label><label class="full">Institution logo (optional, PNG or JPEG up to 5 MB)<input type="file" name="logo" accept="image/png,image/jpeg"></label>${staffLogo?`<p class="help full">Selected: ${esc(staffLogo.name)} - choose a file again only to replace it.</p>`:''}`:''}</div>
<h3>${kind==='delegate'?'Pass holder':'Attendees'}</h3>${kind==='exhibitor'?`<p class="help">This stall includes ${c.roster_count} ${c.roster_count===1?'pass':'passes'}. Add at least one attendee; the rest can be added later from the registration.</p>`:''}${d.attendees.map((p,i)=>staffAttendee(p,i,kind)).join('')}
<h3>Payment</h3><div class="fields"><label class="check"><input type="radio" name="payment" value="complimentary" ${paid?'':'checked'}>Complimentary</label><label class="check"><input type="radio" name="payment" value="paid" ${paid?'checked':''} ${c.free_only?'disabled':''}>Paid - verified bank payment</label></div>${paid?`<p class="help">Enter the transaction as it appears in the bank's reconciliation report. The amount must equal the fee for the payment date${c.coupon_eligible?', less any coupon':''}. Fee for a payment made today: ${money(c.payable_paise)}.</p><div class="fields">${field('Verified bank reference','verified_reference',d.verified_reference,'text','maxlength="100"')}${field('Verified payment date','verified_date',d.verified_date||today,'date',`max="${today}"`)}${field('Verified amount in INR','amount',d.amount||(c.payable_paise/100).toFixed(2),'number','min="0.01" step="0.01"')}${c.coupon_eligible?optField('Coupon code (optional)','coupon_code',d.coupon_code,'text','maxlength="40" autocomplete="off"'):''}</div><label class="check"><input type="checkbox" name="successful" required>I verified the transaction succeeded.</label><label class="check"><input type="checkbox" name="beneficiary_confirmed" required>I verified the correct beneficiary.</label>`:`<p class="help">${c.free_only?'This category is complimentary only. ':''}No payment is recorded.</p>`}
<label>Organiser note (optional)<textarea name="note" maxlength="2000">${esc(d.note)}</textarea></label><div class="actions"><button value="send">Confirm and send passes</button><button value="confirm" class="secondary">Confirm only</button></div><p class="help">Confirm only issues the passes without sending them; send them from the registration when ready.</p></form>`;
window.scrollTo({top:0});const form=document.getElementById('staff-registration');
form.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.tagName==='INPUT')e.preventDefault();});
bind('return','click',()=>{staffDraft=null;staffLogo=null;return adminList();});
form.addEventListener('change',e=>{if(e.target.name==='category_id'||e.target.name==='payment'){staffCapture(form);staffRegistrationPage().catch(err=>message(err.message,true));}});
bind('staff-registration','submit',async e=>{e.preventDefault();staffCapture(form);const c=staffCategory(),d=staffDraft,people=d.attendees.filter((p,i)=>i===0||p.name.trim()||p.email.trim()||p.designation.trim()||p.phone.trim()),first=people[0],body={category_id:c.id,institution:d.institution,contact_name:c.kind==='delegate'?first.name:d.contact_name,email:c.kind==='delegate'?first.email:d.email,phone:c.kind==='delegate'?first.phone:d.phone,description:c.kind==='exhibitor'?d.description:'',coupon_code:d.payment==='paid'?d.coupon_code:'',attendees:people,payment:d.payment,send:e.submitter?.value==='send',note:d.note};if(d.payment==='paid')Object.assign(body,{verified_reference:d.verified_reference,verified_date:d.verified_date,verified_amount_paise:paise(d.amount)});await busy(e.submitter,async()=>{const fd=new FormData();fd.append('payload',JSON.stringify(body));if(c.kind==='exhibitor'&&staffLogo)fd.append('logo',staffLogo);let res;try{res=await fetch('/api/v1/admin/registrations',{method:'POST',headers:{'Idempotency-Key':d.key,'X-CSRF-Token':csrf()},body:fd});}catch{throw Error('Network error. Check your connection and retry.');}await checkStaffResponse(res,'/admin/registrations');const out=await res.json().catch(()=>null);if(!res.ok)throw Error(out?.error||`Request failed (${res.status}). Please retry.`);staffDraft=null;staffLogo=null;await adminDetail(out.id,{push:true});message(body.send?'Registration confirmed. Passes are being sent.':'Registration confirmed. Passes are issued but not sent.');});});}
async function freeLinksPage(revealed=''){const d=await api('/admin/free-links'),now=new Date(d.server_time),parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now),today=`${parts.find(p=>p.type==='year').value}-${parts.find(p=>p.type==='month').value}-${parts.find(p=>p.type==='day').value}`,links=d.items.map(l=>({...l,active:!l.revoked_at&&new Date(l.expires_at)>now,type:l.registration_kind==='exhibitor'?'Exhibitors':'Delegates'}));app.innerHTML=`<button id="return" class="secondary">Back to registrations</button><h1>Free registration links.</h1><p>Create complimentary links for delegates or exhibitors. Generating a replacement expires only the active link for the same registration type.</p><form id="generate-free-link" class="card"><h2>Generate link</h2><label>Registration type<select name="registration_kind"><option value="delegate">Delegates</option><option value="exhibitor">Exhibitors</option></select></label>${field('Usable through','expires_on',today,'date',`min="${today}"`)}<label class="check"><input type="checkbox" name="auto_approve" checked>Approve registrations automatically and issue passes immediately.</label><p class="help">Clear this option when registrations from the link should wait for organiser review. Exhibitors still provide their institution logo and attendee details. The link works through the end of the selected date in India time.</p><button>Generate new link</button></form>${revealed?`<div class="card"><h2>New link</h2><label>Copy and share this link<input id="generated-free-url" class="mono" value="${esc(revealed)}" readonly></label><div class="actions"><button id="copy-free-link">Copy link</button></div><p class="help">For security, this is the only time the complete link is shown.</p></div>`:''}<div class="card"><h2>Link history</h2>${links.length?`<div class="table-scroll"><table><thead><tr><th>Status</th><th>Registration type</th><th>Approval</th><th>Usable through</th><th>Registrations</th><th>Created by</th><th>Action</th></tr></thead><tbody>${links.map(l=>`<tr><td>${l.active?'Active':l.revoked_at?'Expired manually':'Expired'}</td><td>${esc(l.type)}</td><td>${l.auto_approve?'Automatic':'Needs review'}</td><td>${esc(String(l.expires_on).slice(0,10))}</td><td>${esc(l.use_count)}</td><td>${esc(l.created_by)}</td><td>${l.active?`<button class="expire-free-link danger" data-id="${l.id}" data-type="${esc(l.registration_kind)}">Expire this link</button>`:'-'}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No records yet.</p>'}</div>`;window.scrollTo({top:0});bind('return','click',adminList);bind('generate-free-link','submit',async e=>{e.preventDefault();const f=new FormData(e.target),kind=f.get('registration_kind');if(links.some(l=>l.registration_kind===kind&&l.active)&&!confirm(`Generate a new ${kind} link and immediately expire the active one?`))return;await busy(e.submitter,async()=>{const out=await post('/admin/free-links',{registration_kind:kind,expires_on:f.get('expires_on'),auto_approve:f.has('auto_approve')});message('New free registration link generated.');await freeLinksPage(out.url);},'Generating…');});bind('copy-free-link','click',async()=>{await navigator.clipboard.writeText(document.getElementById('generated-free-url').value);message('Free registration link copied.');});document.querySelectorAll('.expire-free-link').forEach(el=>el.addEventListener('click',async()=>{if(!confirm(`Expire this ${el.dataset.type} link now? Anyone using it will no longer be able to register.`))return;try{await post(`/admin/free-links/${el.dataset.id}/expire`,{});message(`${el.dataset.type==='exhibitor'?'Exhibitor':'Delegate'} free registration link expired.`);await freeLinksPage();}catch(err){message(err.message,true);}}));}
async function categoryAdmin(){await loadConfig();app.innerHTML=`<h1>Category availability.</h1><p>Closing stops new registrations. Paid and free-link registration are controlled separately. Existing registrations can still submit payment evidence.</p><div class="card"><div class="table-scroll"><table><thead><tr><th>Category</th><th>Fee</th><th>Paid registration</th><th>Free links</th></tr></thead><tbody>${config.categories.map(c=>`<tr><td>${esc(c.label)}</td><td>${c.free_only?'Free-link only':money(c.payable_paise)}</td><td>${c.free_only?'-':`<label class="check"><input class="category-toggle" type="checkbox" data-id="${c.id}" data-field="open" ${c.open?'checked':''}>Open</label>`}</td><td><label class="check"><input class="category-toggle" type="checkbox" data-id="${c.id}" data-field="free_open" ${c.free_open?'checked':''}>Open</label></td></tr>`).join('')}</tbody></table></div></div><button id="return">Back to registrations</button>`;document.querySelectorAll('.category-toggle').forEach(el=>el.addEventListener('change',async()=>{try{await post('/admin/categories',{id:el.dataset.id,[el.dataset.field]:el.checked});message('Availability saved.');}catch(e){el.checked=!el.checked;message(e.message,true);}}));bind('return','click',adminList);}
async function adminDetail(rid,{push=false,top=false}={}){const d=await api('/admin/registrations/'+rid),r=d.registration;if(d.category.kind==='exhibitor'&&!config)await loadConfig();if(push){history.replaceState({...history.state,scroll:scrollY},'');const p=listParams();p.set('registration',rid);history.pushState({fromList:true},'','?'+p);}app.innerHTML=`<button id="return" class="secondary back-button"><span aria-hidden="true">&larr;</span> Back to registrations</button><h1>${esc(r.reference)}</h1><p><span class="pill">${esc(r.status)}</span> ${esc(d.category.label)}</p><div class="card"><h2>Registration details</h2>${pairs([['Institution',r.institution],['Contact',r.contact_name],['Email',r.email],['Phone',r.phone],['Description',r.description],['Coupon',r.coupon_code?`${r.coupon_code} - ${r.discount_percent}% off, paid by bank transfer`:'None'],['Current fee',money(d.payable_paise)],['Original quote',money(r.quoted_paise)],...assigned(d),['Organiser note',r.review_note]])}${stallNumberForm(d)}${stallForm(d)}${allowanceForm(d)}<h3>Attendees</h3>${attendeeTable(d)}${r.status==='approved'&&d.passes.some(p=>!p.revoked_at)?`<div class="actions pass-pack"><a class="button secondary" href="/api/v1/admin/registrations/${esc(r.id)}/passes/all.zip">Download all passes (ZIP)</a></div>`:''}<div id="attendee-edit"></div><h3>Private files</h3><div class="actions">${d.files.map(f=>`<a class="button secondary" href="/api/v1/admin/registrations/${rid}/files/${f.id}">Download ${esc(f.kind)} (${date(f.created_at)})</a>`).join('')||'No files uploaded.'}</div>${d.category.kind==='exhibitor'&&r.status!=='cancelled'?`<form id="admin-logo-form" class="admin-logo-form"><label>${d.files.some(f=>f.kind==='logo')?'Replace institution logo':'Upload institution logo on the exhibitor’s behalf'} (PNG or JPEG, up to 5 MB)<input type="file" name="logo" accept="image/png,image/jpeg" required></label>${r.status==='approved'?'<p class="help">The public exhibitor directory shows the newest logo.</p>':''}<button>Upload logo</button></form>`:''}</div><div class="card"><h2>Payment submissions</h2>${table(d.payments.map(p=>({...p,amount:money(p.amount_paise),payment_date:date(p.payment_date)})),[['id','Submission ID'],['bank_reference','Reported reference'],['payment_date','Reported date'],['amount','Reported amount'],['verified_reference','Verified reference'],['verified_at','Verified at']])}</div>${r.status==='awaiting_review'?reviewForm(d):r.status==='awaiting_payment'?reviewForm(d,true):r.status==='rejected'?reinstateForm(d):''}${attendeeForm(d,true)}<div class="card"><h2>Registration actions</h2>${openPlaces(d)>0?'<form id="roster-notice-form"><p class="help">Emails the contact how many passes are unassigned and a single-use link to add attendees, valid for 7 days. One notice per registration every 24 hours.</p><button class="secondary">Send add-attendee notice</button></form>':''}${r.status==='awaiting_payment'?'<form id="remind-form"><p class="help">Emails the contact the fee due and a single-use link to this registration, valid for 7 days. One reminder per registration every 24 hours.</p><button class="secondary">Send payment reminder</button></form>':''}${r.status==='approved'?`<form id="send-form"><label>Channel<select name="channel"><option value="">Email and permitted WhatsApp</option><option value="email">Email only</option><option value="whatsapp">Permitted WhatsApp only</option></select></label><div class="actions"><button value="send">Send passes</button><button value="resend" class="secondary">Resend existing passes</button></div><p class="help">Send queues initial delivery once. Resend uses the existing passes.</p></form>`:''}${r.status!=='cancelled'?'<form id="cancel-form"><label>Cancellation reason<textarea name="note" required></textarea></label><p class="help">Cancellation revokes all passes. Handle refunds manually.</p><button class="danger">Cancel registration</button></form>':''}</div><div class="card"><h2>Pass history</h2>${table(d.passes,[['number','Pass number'],['version','Version'],['attendee_id','Attendee ID'],['revoked_at','Revoked at']])}${r.status==='approved'?`<form id="reissue-form"><label>Pass to reissue<select name="pass_id">${d.passes.filter(p=>!p.revoked_at).map(p=>`<option value="${p.id}">${esc(r.attendees.find(a=>a.id===p.attendee_id)?.name)} · ${esc(p.number)}</option>`).join('')}</select></label><label>Reason<textarea name="note" required></textarea></label><p class="help">Reissue revokes the previous pass, its QR identifier and its pass number, and issues a replacement. Nothing is sent: send the new pass from the attendee list when ready.</p><button class="secondary">Reissue pass</button></form>`:''}</div><div class="card"><h2>Delivery history</h2>${table(d.deliveries.map(j=>({...j,created_at:date(j.created_at)})),[['id','Job ID'],['purpose','Purpose'],['channel','Channel'],['recipient','Recipient'],['status','Status'],['attempts','Attempts'],['error_code','Outcome'],['provider_id','Provider ID'],['created_at','Created']])}${d.deliveries.filter(j=>['failed','uncertain'].includes(j.status)).map(j=>`<form class="retry-form" data-id="${j.id}"><p>${esc(j.channel)} · ${esc(j.recipient)} · ${esc(j.status)}</p>${j.status==='uncertain'?'<label class="check"><input type="checkbox" name="confirm_uncertain" required>I checked the provider and accept that retrying may send a duplicate.</label><label>Provider check note<input name="note" required></label>':''}<button class="secondary">Retry ${esc(j.id)}</button></form>`).join('')}</div><div class="card"><h2>Audit trail</h2>${table(d.audit.map(a=>({...a,created_at:date(a.created_at)})),[['created_at','Time'],['staff_email','Staff'],['action','Action'],['detail','Details']])}</div>`;
if(push||top)window.scrollTo({top:0});bind('return','click',e=>busy(e.currentTarget,backToList,'Loading…'));bind('admin-logo-form','submit',async e=>{e.preventDefault();await busy(e.submitter,async()=>{const file=new FormData(e.target).get('logo');await upload(rid,'logo',file,{'X-CSRF-Token':csrf()},'/api/v1/admin/registrations');message('Logo uploaded.');await adminDetail(rid);});});bind('review-form','submit',async e=>{e.preventDefault();await busy(e.submitter,async()=>{const f=new FormData(e.target),action=e.submitter.value;await post(`/admin/registrations/${rid}/review`,{action,note:f.get('note'),payment_id:f.get('payment_id'),verified_reference:f.get('verified_reference'),verified_date:f.get('verified_date'),verified_amount_paise:action.includes('approve')||action==='reinstate'?paise(f.get('amount')):0,successful:f.has('successful'),beneficiary_confirmed:f.has('beneficiary_confirmed')});message('Review saved.');await adminDetail(rid);});});bind('remind-form','submit',async e=>{e.preventDefault();await busy(e.submitter,async()=>{await post(`/admin/registrations/${rid}/review`,{action:'payment_reminder'});message('Payment reminder queued.');await adminDetail(rid);},'Sending…');});bind('roster-notice-form','submit',async e=>{e.preventDefault();await busy(e.submitter,async()=>{await post(`/admin/registrations/${rid}/review`,{action:'roster_notice'});message('Add-attendee notice queued.');await adminDetail(rid);},'Sending…');});bind('attendee-form','submit',async e=>{e.preventDefault();await busy(e.submitter,async()=>{await post(`/admin/registrations/${rid}/attendees`,attendeeBody(e.target));message('Attendee added.');await adminDetail(rid);});});bind('send-form','submit',async e=>{e.preventDefault();await busy(e.submitter,async()=>{await post(`/admin/registrations/${rid}/review`,{action:e.submitter.value,channel:new FormData(e.target).get('channel'),request_id:uuid()});message('Delivery queued.');await adminDetail(rid);});});
bindAttendeeActions(d);bind('allowance-form','submit',async e=>{e.preventDefault();const f=new FormData(e.target);await busy(e.submitter,async()=>{await post(`/admin/registrations/${rid}/allowance`,{roster_count:Number(f.get('roster_count')),note:f.get('note')});message(`Pass allowance set to ${f.get('roster_count')}.`);await adminDetail(rid);});});bind('stall-number-form','submit',async e=>{e.preventDefault();const f=new FormData(e.target),n=String(f.get('stall_number')).trim();await busy(e.submitter,async()=>{await post(`/admin/registrations/${rid}/stall-number`,{stall_number:n,note:f.get('note')});message(n?`Stall number set to ${n.toUpperCase()}.`:'Stall allocation cleared.');await adminDetail(rid);});});bind('category-form','submit',async e=>{e.preventDefault();const f=new FormData(e.target),to=config.categories.find(c=>c.id===f.get('category_id')),extra=Math.max(r.attendees.length-to.roster_count,0);if(!confirm(`Move ${r.reference} to ${to.label} (${to.roster_count} passes)?${extra?` All ${r.attendees.length} attendees keep their passes; ${extra} ${extra===1?'becomes an extra pass':'become extra passes'}.`:''} Nothing is sent to the exhibitor.`))return;await busy(e.submitter,async()=>{await post(`/admin/registrations/${rid}/category`,{category_id:f.get('category_id'),note:f.get('note')});message(`Stall type changed to ${to.label}.`);await adminDetail(rid);});});
for(const [form,action]of [['cancel-form','cancelled'],['reissue-form','reissue']])bind(form,'submit',async e=>{e.preventDefault();await busy(e.submitter,async()=>{await post(`/admin/registrations/${rid}/review`,{action,...Object.fromEntries(new FormData(e.target))});message('Action saved.');await adminDetail(rid);});});
document.querySelectorAll('.retry-form').forEach(el=>el.addEventListener('submit',async e=>{e.preventDefault();try{await busy(e.submitter,async()=>{const f=new FormData(el);await post('/admin/retry',{id:el.dataset.id,confirm_uncertain:f.has('confirm_uncertain'),note:f.get('note')||''});message('Retry queued.');await adminDetail(rid);});}catch(e){message(e.message,true);}}));}
// Staff corrections never deliver anything on their own: each pass is sent
// from its row here, or with "Send passes", once the team is ready.
function activePass(d,aid){return d.passes.find(p=>p.attendee_id===aid&&!p.revoked_at);}
function passSent(d,pass){return d.deliveries.some(j=>j.pass_id===pass.id&&j.purpose==='pass'&&j.status!=='cancelled');}
function attendeeTable(d){const r=d.registration;if(!r.attendees.length)return '<p class="muted">No records yet.</p>';const editable=r.status!=='cancelled',approved=r.status==='approved';return `<div class="table-scroll"><table><thead><tr><th scope="col">Name</th><th scope="col">Designation</th><th scope="col">Email</th><th scope="col">Phone</th><th scope="col">WhatsApp</th>${approved?'<th scope="col">Pass</th>':''}${editable?'<th scope="col">Actions</th>':''}</tr></thead><tbody>${r.attendees.map(a=>{const pass=activePass(d,a.id),sent=pass&&passSent(d,pass);return `<tr><td>${esc(a.name)}</td><td>${esc(a.designation)}</td><td>${esc(a.email)}</td><td>${esc(a.phone)}</td><td>${a.whatsapp_consent?'Permitted':'Not permitted'}</td>${approved?`<td>${pass?`<span class="mono">${esc(pass.number)}</span><br><small>${sent?'Sent':'Not sent'}</small>`:'-'}</td>`:''}${editable?`<td><div class="row-actions">${approved&&pass?`<button type="button" class="send-pass" data-pass="${esc(pass.id)}" data-action="${sent?'resend':'send'}" data-name="${esc(a.name)}">${sent?'Resend pass':'Send pass'}</button><a class="button secondary" href="/api/v1/admin/registrations/${esc(r.id)}/passes/${esc(pass.id)}.pdf">Download pass</a>`:''}<button type="button" class="secondary edit-attendee" data-id="${esc(a.id)}">Edit</button>${r.attendees.length>1?`<button type="button" class="danger remove-attendee" data-id="${esc(a.id)}" data-name="${esc(a.name)}">Remove</button>`:''}</div></td>`:''}</tr>`;}).join('')}</tbody></table></div>`;}
function attendeeEditForm(d,a){const pass=d.registration.status==='approved'&&activePass(d,a.id);return `<form id="attendee-edit-form" class="inline-form" data-id="${esc(a.id)}"><h3>Edit ${esc(a.name)}</h3><div class="fields">${field('Full name','name',a.name,'text','maxlength="120"')}${field('Designation','designation',a.designation,'text','maxlength="180"')}${field('Email','email',a.email,'email')}${field('Phone (e.g. +919876543210)','phone',a.phone,'tel','pattern="\\+[1-9][0-9]{7,14}"')}</div><label class="check"><input type="checkbox" name="whatsapp_consent" ${a.whatsapp_consent?'checked':''}>I have permission to send this attendee their Bio Connect 4.0 pass and delivery updates by WhatsApp.</label><p class="help">Saving sends nothing.${pass?' The pass keeps its number and QR code and shows the new details when next downloaded. If it was already sent, resend it so the attendee has the updated copy.':''}${d.category.kind==='delegate'?' The registration contact is updated to match.':''}</p><div class="actions"><button>Save attendee</button><button type="button" id="attendee-edit-cancel" class="secondary">Cancel</button></div></form>`;}
function bindAttendeeActions(d){const r=d.registration,rid=r.id,holder=document.getElementById('attendee-edit');
document.querySelectorAll('.edit-attendee').forEach(el=>el.addEventListener('click',()=>{message('');holder.innerHTML=attendeeEditForm(d,r.attendees.find(a=>a.id===el.dataset.id));holder.querySelector('input')?.focus();bind('attendee-edit-cancel','click',()=>{holder.innerHTML='';});bind('attendee-edit-form','submit',async e=>{e.preventDefault();await busy(e.submitter,async()=>{await post(`/admin/registrations/${rid}/attendees/${e.target.dataset.id}`,attendeeBody(e.target));message('Attendee updated. Nothing was sent.');await adminDetail(rid);});});}));
document.querySelectorAll('.remove-attendee').forEach(el=>el.addEventListener('click',async()=>{message('');if(!confirm(`Remove ${el.dataset.name} from ${r.reference}?${r.status==='approved'?' Their pass and QR code are revoked.':''}`))return;try{await busy(el,async()=>{await post(`/admin/registrations/${rid}/attendees/${el.dataset.id}/remove`,{note:''});message(`${el.dataset.name} removed.`);await adminDetail(rid);},'Removing…');}catch(err){message(err.message,true);}}));
document.querySelectorAll('.send-pass').forEach(el=>el.addEventListener('click',async()=>{message('');try{await busy(el,async()=>{await post(`/admin/registrations/${rid}/review`,{action:el.dataset.action,pass_id:el.dataset.pass,request_id:uuid()});message(`Pass queued for ${el.dataset.name}.`);await adminDetail(rid);},'Sending…');}catch(err){message(err.message,true);}}));}
function stallNumberForm(d){const r=d.registration;if(d.category.kind!=='exhibitor'||r.status==='cancelled')return '';return `<form id="stall-number-form" class="inline-form"><div class="fields"><label>Stall number<input name="stall_number" maxlength="16" value="${esc(r.stall_number||'')}" placeholder="e.g. A-12" autocomplete="off"></label><label>Reason (optional)<input name="note" maxlength="2000"></label></div><p class="help">${r.stall_number?`Currently stall ${esc(r.stall_number)}.`:'No stall allocated yet.'} Approved exhibitors appear in the public directory and the mobile app with this number. Leave it empty to clear the allocation. Nothing is sent.</p><div class="actions"><button class="secondary">Save stall number</button></div></form>`;}
function stallForm(d){const r=d.registration;if(d.category.kind!=='exhibitor'||r.status==='cancelled'||!config)return '';const others=config.categories.filter(c=>c.kind==='exhibitor'&&c.id!==r.category_id);if(!others.length)return '';return `<form id="category-form" class="inline-form"><div class="fields"><label>Change stall type<select name="category_id">${others.map(c=>`<option value="${esc(c.id)}">${esc(c.label)} · ${c.roster_count} passes</option>`).join('')}</select></label><label>Reason (optional)<input name="note" maxlength="2000"></label></div><p class="help">Passes follow the new stall's allowance and keep any extra passes granted. Moving to a smaller stall removes nobody: attendees beyond the new allowance stay as extra passes. Issued passes, the reference and payments stay as they are, and nothing is sent.${r.status==='approved'?' Settle any fee difference outside the system.':''}</p><div class="actions"><button class="secondary">Change stall type</button></div></form>`;}
function allowanceForm(d){const r=d.registration,included=d.category.roster_count;if(d.category.kind!=='exhibitor'||r.status==='cancelled')return '';return `<form id="allowance-form" class="inline-form"><div class="fields"><label>Pass allowance<input name="roster_count" type="number" min="${Math.max(1,r.attendees.length)}" max="50" step="1" value="${r.roster_count}" required></label><label>Reason (optional)<input name="note" maxlength="2000"></label></div><p class="help">${esc(d.category.label)} includes ${included} passes${r.roster_count>included?`; this registration has ${r.roster_count-included} extra`:''}. Raise it to add extra passes, then fill them with Add an attendee below. Nothing is sent, and any fee is settled outside the system.</p><div class="actions"><button class="secondary">Save pass allowance</button></div></form>`;}
function reinstateForm(d){const free=d.registration.free_registration,p=d.payments[0];return `<form id="review-form" class="card"><h2>Approve rejected registration</h2><p>${free?'This registration is complimentary. No payment verification is required.':'Verify the payment against the bank’s reconciliation report, entering the transaction as it appears there.'} Approval issues the passes without sending them. Send them from the attendee list or with Send passes when ready.</p>${free?'<input type="hidden" name="amount" value="0.01">':`<input type="hidden" name="payment_id" value="${esc(p?.id)}">${p?`<p class="help">Latest submission: ${esc(p.bank_reference)} · ${money(p.amount_paise)} · ${day(p.payment_date)}</p>`:''}<div class="fields">${field('Verified bank reference','verified_reference')}${field('Verified payment date','verified_date','','date')}${field('Verified amount in INR','amount','','number','min="0.01" step="0.01"')}</div><label class="check"><input type="checkbox" name="successful" required>I verified the transaction succeeded.</label><label class="check"><input type="checkbox" name="beneficiary_confirmed" required>I verified the correct beneficiary.</label>`}<label>Review note<textarea name="note"></textarea></label><div class="actions"><button value="reinstate">Approve without sending</button></div></form>`;}
function reviewForm(d,record=false){if(d.registration.free_registration)return `<form id="review-form" class="card"><h2>Review complimentary registration</h2><p>This registration is complimentary. No payment verification is required.</p><input type="hidden" name="amount" value="0.01"><label>Review note / rejection reason<textarea name="note"></textarea></label><div class="actions"><button value="approve_send">Approve and send pass</button><button value="approve_only" class="secondary">Approve only</button><button value="rejected" class="danger" formnovalidate>Reject</button></div></form>`;const missingLogo=record&&d.category.kind==='exhibitor'&&!d.files.some(f=>f.kind==='logo');return `<form id="review-form" class="card"><h2>${record?'Record payment found in SBI':'Verify against bank records'}</h2><p>${record?'Use this only when SBI confirms a payment that the registrant did not submit. This creates the payment record and approves the registration.':'Approve only against the bank’s reconciliation report, entering the transaction as it appears there.'}</p>${missingLogo?'<div class="banner warning"><strong>Institution logo missing.</strong> Upload it above on the exhibitor’s behalf, or ask them to add it themselves, before recording and approving this payment.</div>':''}<input type="hidden" name="payment_id" value="${esc(d.payments[0]?.id)}"><div class="fields">${field('Verified bank reference','verified_reference')}${field('Verified payment date','verified_date','','date')}${field('Verified amount in INR','amount','','number','min="0.01" step="0.01"')}</div><label class="check"><input type="checkbox" name="successful" required>I verified the transaction succeeded.</label><label class="check"><input type="checkbox" name="beneficiary_confirmed" required>I verified the correct beneficiary.</label><label>${record?'Review note':'Review note / correction or rejection reason'}<textarea name="note"></textarea></label><div class="actions">${record?`<button value="record_approve_send" ${missingLogo?'disabled':''}>Record, approve and send</button><button value="record_approve_only" class="secondary" ${missingLogo?'disabled':''}>Record and approve only</button>`:'<button value="approve_send">Approve and send</button><button value="approve_only" class="secondary">Approve only</button><button value="correction_requested" class="secondary" formnovalidate>Request correction</button><button value="rejected" class="danger" formnovalidate>Reject</button>'}</div></form>`;}
async function accountsPage(){const accounts=await api('/admin/staff');app.innerHTML=`<h1>Staff accounts.</h1><p>Account managers administer access. Reviewers administer registrations and payments.</p><div class="admin-header-actions"><button id="mobile-app" class="secondary">Mobile app</button><button id="posters" class="secondary">Social posters</button><button id="logout" class="quiet">Sign out</button></div><div class="card">${table(accounts,[['email','Email'],['role','Role'],['active','Active']])}</div><form id="create-account" class="card"><h2>Create individual account</h2><div class="fields">${field('Email','email','','email')}${field('Password (14-72 bytes)','password','','password','minlength="14" maxlength="72"')}<label>Role<select name="role"><option value="reviewer">Registration reviewer</option><option value="manager">Account manager</option></select></label></div><button>Create account</button><p id="enrollment" class="secret" hidden></p></form><form id="edit-account" class="card"><h2>Change access</h2><label>Account<select name="id">${accounts.filter(a=>a.id!==me.id).map(a=>`<option value="${a.id}">${esc(a.email)}</option>`).join('')}</select></label><label>Role<select name="role"><option value="reviewer">Registration reviewer</option><option value="manager">Account manager</option></select></label><label class="check"><input type="checkbox" name="active" checked>Active</label><p class="help">Changing access ends existing sessions for this account.</p><button>Save access</button></form>`;logout();bind('posters','click',()=>posterHome());bind('mobile-app','click',()=>{history.pushState(null,'','/admin?view=mobile');return mobileContentPage();});bind('create-account','submit',async e=>{e.preventDefault();await busy(e.submitter,async()=>{const out=await post('/admin/staff',Object.fromEntries(new FormData(e.target)));e.target.reset();const el=document.getElementById('enrollment');el.hidden=false;el.textContent='Share securely with this staff member and add to their authenticator: '+out.totp_uri;message('Account created. TOTP is mandatory at sign in.');});});bind('edit-account','submit',async e=>{e.preventDefault();await busy(e.submitter,async()=>{const f=new FormData(e.target);await post('/admin/staff',{id:f.get('id'),role:f.get('role'),active:f.has('active')});message('Access updated and sessions revoked.');await accountsPage();});});}
(async()=>{try{await loadConfig();if(path==='/delegates'||path==='/exhibitors'){await loadFreeRegistration();formPage();setInterval(async()=>{try{const old=category()?.payable_paise;await loadConfig();const c=category(),el=document.getElementById('current-fee');if(el&&!freeRegistration)el.textContent=money(offer(c.payable_paise));const was=document.getElementById('published-fee');if(was)was.textContent=money(c.payable_paise);if(old!==c.payable_paise&&!freeRegistration)message('Fees have refreshed for the current date. Verified timely payments remain eligible for early-bird fees.');}catch{}},60000);}else if(path.startsWith('/manage/'))await managePage();else if(path==='/recover')await recoveryPage();else if(path==='/admin')await adminPage();}catch(e){app.innerHTML='<h1>We could not load this page.</h1><p>Your saved registration is safe. <a href="">Try again</a> or <a href="/recover">recover by email</a>.</p>';message(e.message,true);}})();
